INSERT INTO public.pages (id, title, content)
VALUES (
  'home',
  'Halaman Beranda',
  '{"hero":{"tagline":"PT NIAGA JAMINAN NUSANTARA","title":"Jasa Bank Garansi & Surety Bond Terpercaya di Indonesia","description":"Layanan Penerbitan Bank Garansi dan Surety Bond cepat tanpa agunan (Non Collateral) dan dengan agunan (Collateral) untuk berbagai keperluan proyek pemerintah maupun swasta di seluruh wilayah Indonesia. Proses mudah, syarat ringan, legalitas resmi, dan terdaftar di OJK.","ctaConsultationText":"KONSULTASI SEKARANG","badgeItems":["Tanpa Agunan","Resmi OJK","Proses Cepat","Se-Indonesia"],"medallionImage":"/images/gold-seal.jpg"},"whatIs":{"title":"Apa Itu Jasa Surety Bond?","intro":"Jasa surety bond merupakan layanan penerbitan jaminan proyek yang melibatkan tiga pihak:","parties":[{"name":"Obligee","description":"pemilik proyek (pemberi kerja / instansi pemerintah atau swasta)"},{"name":"Principal","description":"kontraktor / pelaksana yang mengerjakan proyek"},{"name":"Surety","description":"perusahaan asuransi penjamin resmi yang menerbitkan jaminan"}],"paragraphs":["Melalui instrumen ini, pemilik proyek mendapatkan kepastian bahwa proyek akan selesai sesuai kontrak, sementara kontraktor dapat memenuhi persyaratan tender tanpa harus mengendapkan modal tunai berlebih.","Layanan kami mempermudah proses ini secara legal, transparan, dan terpercaya untuk memastikan kelancaran bisnis dan reputasi perusahaan Anda."]},"functions":{"title":"Fungsi Jasa Surety Bond Resmi","items":[{"icon":"ShieldCheck","title":"Memberikan Jaminan Kepastian Proyek","description":"Melindungi pemilik proyek dari risiko wanprestasi oleh kontraktor. Jaminan ini memberikan kepastian hukum dan finansial sepanjang masa pelaksanaan proyek hingga serah terima."},{"icon":"TrendingUp","title":"Meningkatkan Kredibilitas Perusahaan","description":"Membantu kontraktor memperbesar peluang memenangkan tender dengan melampirkan jaminan resmi dari institusi penjamin terpercaya dan teregulasi OJK."},{"icon":"FileCheck2","title":"Menjadi Syarat Tender Pemerintah","description":"Memenuhi ketentuan pengadaan barang dan jasa pemerintah (LPSE, LKPP) maupun BUMN yang mewajibkan adanya jaminan penawaran dan jaminan pelaksanaan."}]},"whyNeeded":{"badge":"KONSULTAN RESMI BERPENGALAMAN","companyTag":"PT NIAGA JAMINAN NUSANTARA","bannerImage":"/images/banner-jaminan.jpg","phoneDisplay":"0811-4066-5585","phoneCall":"081140665585","eyebrow":"JASA BANK GARANSI & SURETY BOND TERPERCAYA DI INDONESIA","title":"Mengapa Surety Bond Semakin Dibutuhkan dalam Proyek Modern?","paragraphs":["Dalam iklim bisnis modern yang kompetitif dan berisiko tinggi, instrumen penjaminan finansial bukan lagi sekadar formalitas administratif, melainkan benteng pertahanan krusial bagi kelangsungan proyek.","Meningkatnya kompleksitas rantai pasok global dan fluktuasi ekonomi menuntut kepastian hukum serta mitigasi risiko yang solid antara kontraktor (principal) dan pemilik proyek (obligee).","Surety bond hadir sebagai solusi cerdas yang menguntungkan kedua belah pihak: membebaskan modal kerja kontraktor tanpa perlu mengendapkan agunan tunai penuh, sekaligus memberikan garansi pemulihan kerugian finansial bagi obligee jika terjadi wanprestasi."],"ctaCardTitle":"Hubungi Kami Sekarang:","ctaCardDescription":"Konsultasikan kebutuhan jaminan proyek Anda bersama tim ahli kami. Proses cepat, legalitas terjamin, tanpa agunan menyulitkan!","ctaButtonText":"KONSULTASI GRATIS"},"products":{"eyebrow":"PRODUK & LAYANAN","title":"Solusi Penjaminan & Asuransi Lengkap","description":"Mendukung perusahaan Anda dalam memenuhi persyaratan tender, kontrak, serta perlindungan operasional bisnis.","suretySectionTitle":"Surety Bond & Bank Garansi","suretySectionDescription":"NJN menyediakan solusi penjaminan untuk mendukung perusahaan dalam mengikuti proses tender, memenuhi persyaratan kontrak, serta menjalankan kewajiban dalam berbagai proyek dan kegiatan bisnis.","suretyItems":[{"icon":"FileText","title":"Bid Bond / Jaminan Penawaran","description":"Mendukung pemenuhan persyaratan jaminan pada proses tender atau pelelangan.","stage":"Tahap Tender / Pelelangan"},{"icon":"Building2","title":"Performance Bond / Jaminan Pelaksanaan","description":"Memberikan dukungan jaminan atas pelaksanaan pekerjaan sesuai ketentuan kontrak.","stage":"Tahap Pelaksanaan Pekerjaan"},{"icon":"Coins","title":"Advance Payment Bond / Jaminan Uang Muka","description":"Mendukung kebutuhan jaminan atas uang muka yang diberikan dalam pelaksanaan proyek.","stage":"Tahap Penarikan Uang Muka"},{"icon":"Award","title":"Maintenance Bond / Jaminan Pemeliharaan","description":"Mendukung kewajiban kontraktor atau penyedia jasa selama periode pemeliharaan pekerjaan.","stage":"Tahap Masa Pemeliharaan (Retensi)"},{"icon":"Shield","title":"Bank Garansi","description":"Solusi jaminan untuk berbagai kebutuhan kontraktual, proyek, pengadaan, dan kegiatan bisnis sesuai persyaratan yang berlaku.","stage":"Mitra Bank BUMN & Bank Swasta Nasional","highlightBadge":"Tersedia Non-Collateral"}],"insuranceEyebrow":"PERLINDUNGAN RISIKO BISNIS","insuranceTitle":"GENERAL INSURANCE","insuranceDescription":"NJN juga membantu menyediakan solusi perlindungan terhadap berbagai risiko yang dapat memengaruhi kegiatan operasional, aset, proyek, maupun tanggung jawab perusahaan.","insuranceSubtitle":"PRODUK YANG DAPAT DISESUAIKAN DENGAN KEBUTUHAN ANTARA LAIN:","insuranceItems":[{"icon":"HardHat","title":"Contractor''s All Risk (CAR)","description":"Perlindungan terhadap berbagai risiko dalam pelaksanaan proyek konstruksi."},{"icon":"Factory","title":"Erection All Risk (EAR)","description":"Perlindungan atas risiko yang berkaitan dengan pemasangan atau instalasi mesin dan peralatan."},{"icon":"Scale","title":"Commercial General Liability (CGL)","description":"Perlindungan terhadap risiko tanggung jawab hukum perusahaan kepada pihak ketiga."},{"icon":"Briefcase","title":"Professional Liability","description":"Perlindungan terhadap risiko yang timbul dari pelaksanaan jasa atau tanggung jawab profesional."},{"icon":"Truck","title":"Marine Cargo","description":"Perlindungan terhadap risiko barang selama proses pengangkutan."},{"icon":"Building","title":"Property Insurance","description":"Perlindungan terhadap aset dan properti perusahaan."},{"icon":"Wrench","title":"Engineering Insurance","description":"Perlindungan terhadap berbagai risiko yang berkaitan dengan mesin, instalasi, dan kegiatan teknik."},{"icon":"ShieldCheck","title":"Asuransi Umum Lainnya","description":"Solusi perlindungan lainnya yang dapat disesuaikan dengan karakteristik risiko dan kebutuhan bisnis klien."}]},"whyUs":{"eyebrow":"KEUNGGULAN KAMI","title":"MENGAPA MEMILIH NJN?","description":"NJN hadir sebagai mitra terpercaya untuk memberikan solusi jaminan dan perlindungan yang tepat, cepat, dan sesuai kebutuhan bisnis Anda.","items":[{"icon":"Clock","title":"RESPONS CEPAT & PROFESIONAL","description":"Mengutamakan respons yang cepat, komunikasi yang jelas, serta pelayanan profesional untuk mendukung kebutuhan tender, proyek, dan aktivitas bisnis yang memiliki batas waktu."},{"icon":"Target","title":"SOLUSI SESUAI KEBUTUHAN","description":"Memahami kebutuhan dan karakteristik bisnis klien untuk memberikan solusi jaminan dan perlindungan yang tepat serta sesuai dengan kondisi masing-masing."},{"icon":"BadgeCheck","title":"TRANSPARAN & TERPERCAYA","description":"Memberikan informasi yang jelas mengenai persyaratan, tahapan, dan proses pengajuan sehingga klien merasa lebih aman dan nyaman."},{"icon":"Layers","title":"SOLUSI TERINTEGRASI","description":"Menghadirkan layanan Bank Garansi, Surety Bond, dan General Insurance dalam satu solusi yang praktis untuk memenuhi berbagai kebutuhan jaminan dan perlindungan bisnis."},{"icon":"HeartHandshake","title":"PENDAMPINGAN JANGKA PANJANG","description":"Tidak hanya fokus pada transaksi, NJN berkomitmen membangun hubungan jangka panjang melalui pendampingan dan dukungan sesuai perkembangan kebutuhan klien."}]},"experience":{"badgeIcon":"ShieldCheck","cardTitle":"PENGALAMAN & KOMPETENSI","cardDescription":"PT Niaga Jaminan Nusantara dibangun dengan fokus pada penyediaan solusi Bank Guarantee, Surety Bond, dan General Insurance untuk berbagai kebutuhan bisnis dan proyek.","cardHighlights":["Profesional & Responsif","Pendekatan Konsultatif"],"eyebrow":"KOMPETENSI KAMI","title":"Landasan Pengalaman untuk Menjawab Kebutuhan Setiap Klien","paragraphs":["Dalam menjalankan kegiatan usahanya, NJN didukung oleh pemahaman dan pengalaman tim dalam menangani kebutuhan jaminan proyek, tender, konstruksi, pengadaan, serta perlindungan terhadap risiko bisnis. Pengalaman tersebut menjadi landasan bagi NJN dalam memberikan pelayanan yang responsif, profesional, serta berorientasi pada kebutuhan setiap klien.","Melalui pendekatan konsultatif, NJN membantu klien mengidentifikasi kebutuhan jaminan dan perlindungan yang sesuai sehingga proses bisnis maupun pelaksanaan proyek dapat berjalan dengan lebih terarah."]},"sectors":{"eyebrow":"SEKTOR INDUSTRI","title":"BIDANG YANG KAMI LAYANI","description":"Solusi penjaminan dan perlindungan risiko untuk berbagai sektor usaha strategis:","items":[{"icon":"HardHat","title":"KONSTRUKSI & INFRASTRUKTUR","description":"Mendukung kebutuhan jaminan dan perlindungan risiko dalam pelaksanaan proyek konstruksi dan infrastruktur."},{"icon":"FileCheck2","title":"TENDER & PENGADAAN","description":"Membantu perusahaan dalam memenuhi kebutuhan jaminan yang diperlukan pada proses tender, pengadaan, maupun pelaksanaan kontrak."},{"icon":"Briefcase","title":"KONSULTANSI","description":"Menyediakan solusi perlindungan yang berkaitan dengan tanggung jawab profesional serta risiko dalam pelaksanaan kegiatan jasa konsultansi."},{"icon":"Truck","title":"PERDAGANGAN & SUPPLIER","description":"Mendukung kebutuhan jaminan dan perlindungan dalam hubungan kontraktual, kegiatan perdagangan, distribusi, serta penyediaan barang dan jasa."}]},"ctaBottom":{"eyebrow":"JASA SURETY BOND & BANK GARANSI RESMI","title":"Niaga Jaminan Nusantara Penerbitan Jaminan","description":"Temukan solusi penjaminan finansial dan perlindungan risiko bisnis terbaik untuk perusahaan Anda. Kami siap melayani pengajuan cepat, aman, dan tanpa agunan menyulitkan di seluruh Indonesia. Hubungi konsultan profesional kami sekarang untuk konsultasi gratis dan penawaran terbaik!","buttonText":"KONSULTASI GRATIS SEKARANG"},"seo":{"title":"PT Niaga Jaminan Nusantara - Jasa Bank Garansi & Surety Bond Terpercaya","description":"Layanan penerbitan Bank Garansi dan Surety Bond cepat tanpa agunan (Non Collateral) dan dengan agunan (Collateral) untuk berbagai proyek di seluruh Indonesia. Resmi, legal, dan terdaftar OJK.","keywords":["Bank Garansi","Surety Bond","Jasa Bank Garansi","Bid Bond","Performance Bond","Advance Payment Bond","Maintenance Bond","PT Niaga Jaminan Nusantara","Asuransi Proyek","Jaminan Tender"]}}'::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.pages (id, title, content)
VALUES (
  'tentang-kami',
  'Tentang Kami',
  '{"profile":{"bannerImage":"/images/banner-jaminan.jpg","bannerTitle":"PT Niaga Jaminan Nusantara (NJN)","bannerSubtitle":"Didirikan oleh Dafinah Syafa Niaga dan Anta Rahmadan","bannerIcon":"ShieldCheck","eyebrow":"PROFIL PERUSAHAAN","title":"Solusi Jaminan dan Perlindungan Risiko Bisnis Terpercaya","paragraphs":["**PT Niaga Jaminan Nusantara (NJN)** merupakan perusahaan yang bergerak dalam bidang layanan penjaminan dan perlindungan risiko bisnis, mencakup aktivitas agen asuransi, agen penjaminan, serta broker penjaminan. Perusahaan mulai beroperasi pada tahun 2020 di Bekasi, Jawa Barat, dan didirikan oleh **Dafinah Syafa Niaga** dan **Anta Rahmadan**.","NJN hadir untuk membantu perusahaan memperoleh solusi jaminan dan perlindungan yang tepat dalam mendukung aktivitas bisnis, tender, pengadaan, maupun pelaksanaan proyek. Dengan mengedepankan profesionalisme, kecepatan pelayanan, transparansi, dan integritas, NJN berupaya memberikan proses layanan yang mudah dipahami serta sesuai dengan kebutuhan setiap klien.","Lebih dari sekadar penyedia layanan, NJN berkomitmen membangun hubungan bisnis jangka panjang dan menjadi mitra yang dapat diandalkan dalam mendukung keberlangsungan serta pengembangan usaha klien."]},"pillars":[{"icon":"Calendar","title":"BEROPERASI SEJAK 2020","description":"Melayani kebutuhan jaminan dan perlindungan bisnis secara profesional."},{"icon":"Layers","title":"LAYANAN UTAMA","description":"Bank Guarantee, Surety Bond, dan General Insurance."},{"icon":"Award","title":"KOMITMEN KAMI","description":"Profesional, responsif, transparan, dan terpercaya."}],"visionMission":{"eyebrow":"VISI & MISI","title":"Visi & Misi Perusahaan","visionTitle":"VISI","visionStatement":"“Menjadi mitra terpercaya dalam menyediakan solusi jaminan dan perlindungan bisnis di Indonesia.”","visionFooter":"PT Niaga Jaminan Nusantara","missionTitle":"MISI","missionPoints":["Memberikan solusi jaminan dan perlindungan yang sesuai dengan kebutuhan serta karakteristik bisnis setiap klien.","Mengutamakan kecepatan, ketepatan, transparansi, dan profesionalisme dalam setiap layanan.","Memberikan kemudahan dan pendampingan untuk membantu klien menjalankan serta mengembangkan peluang bisnisnya.","Menjalankan setiap proses bisnis dengan prinsip integritas, tanggung jawab, dan komitmen terhadap kepercayaan klien."]},"cta":{"eyebrow":"MULAI KONSULTASI HARI INI","title":"Siap Memenangkan Tender dan Mengamankan Proyek Anda?","description":"Tim konsultan PT Niaga Jaminan Nusantara siap memberikan solusi penerbitan Bank Garansi, Surety Bond, dan General Insurance terbaik untuk kebutuhan perusahaan Anda. Konsultasi gratis tanpa komitmen!","buttonConsultation":"Ajukan Penjaminan Sekarang","buttonWhatsapp":"Hubungi via WhatsApp"},"seo":{"title":"Tentang Kami - Profil Perusahaan | PT Niaga Jaminan Nusantara","description":"Profil PT Niaga Jaminan Nusantara (NJN), didirikan oleh Dafinah Syafa Niaga dan Anta Rahmadan sejak tahun 2020. Solusi agen dan konsultan resmi Bank Garansi & Surety Bond terpercaya di Indonesia.","keywords":["Tentang PT Niaga Jaminan Nusantara","Profil NJN","Dafinah Syafa Niaga","Anta Rahmadan","Agen Asuransi Bank Garansi","Broker Penjaminan Proyek","Sejarah PT Niaga Jaminan Nusantara"]}}'::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.pages (id, title, content)
VALUES (
  'layanan',
  'Layanan Service',
  '{"header":{"tagline":"PT NIAGA JAMINAN NUSANTARA","title":"Produk & Layanan Kami","description":"Melayani berbagai kebutuhan jaminan dan asuransi untuk mendukung kesuksesan proyek dan bisnis Anda."},"suretyCard":{"title":"Surety Bond","icon":"FileText","items":["Bid Bond (Jaminan Penawaran)","Performance Bond (Jaminan Pelaksanaan)","Advance Payment Bond (Jaminan Uang Muka)","Maintenance Bond (Jaminan Pemeliharaan)"],"quote":"“Jaminan yang Menguatkan Kepercayaan”","buttonText":"Konsultasi"},"bankCard":{"title":"Bank Garansi","icon":"Landmark","items":["Non-Collateral (Tanpa Setoran Tunai Penuh)","Cash Collateral","Fasilitas Bank (BUMN & Bank Swasta Terkemuka)"],"quote":"“Cepat, Fleksibel, Tanpa Ribet”","buttonText":"Konsultasi"},"insuranceList":{"eyebrow":"PRODUK ASURANSI LENGKAP","title":"Perlindungan Risiko Bisnis & Konstruksi","items":[{"icon":"HardHat","title":"Asuransi Konstruksi","subtitle":"CAR (Contractor All Risk)","extra":"(Construction All Risk)","topic":"Asuransi Konstruksi CAR"},{"icon":"Shield","title":"Asuransi Umum","subtitle":"CGL (Commercial General Liability)","extra":"Asuransi Properti, dan lainnya","topic":"Asuransi Umum & CGL"},{"icon":"UserCheck","title":"Professional Indemnity","subtitle":"(Tanggung Jawab Profesional)","extra":"","topic":"Professional Indemnity"},{"icon":"Ship","title":"Cargo & Engineering","subtitle":"(Pengangkutan Barang & Risiko Teknik)","extra":"","topic":"Cargo & Engineering"},{"icon":"FileText","title":"Asuransi Lainnya","subtitle":"Sesuai kebutuhan proyek dan bisnis Anda","extra":"","topic":"Asuransi Custom Lainnya"}]},"details":{"eyebrow":"INFORMASI DETAIL PRODUK","title":"Karakteristik & Keunggulan Setiap Layanan","description":"Pelajari fungsi dan kegunaan masing-masing jaminan agar tepat sasaran sesuai klausul Rencana Kerja dan Syarat-syarat (RKS) lelang Anda.","items":[{"icon":"ShieldCheck","title":"Jaminan Penawaran (Bid Bond)","description":"Menjamin kesungguhan Principal dalam mengajukan penawaran lelang tender. Jika Principal mengundurkan diri setelah memenangkan tender atau menolak menandatangani kontrak, penjamin akan membayar ganti rugi sesuai nilai jaminan kepada Obligee.","badge":"Masa laku: 30 - 180 hari kalender"},{"icon":"Zap","title":"Jaminan Pelaksanaan (Performance Bond)","description":"Menjamin bahwa Principal akan menyelesaikan pekerjaan sesuai spesifikasi teknis, gambar kerja, dan jadwal waktu yang tercantum di dalam Kontrak Kerja/SPK (umumnya senilai 5% dari total nilai kontrak).","badge":"Masa laku: Sejak SPK terbit hingga BAST-1"},{"icon":"Landmark","title":"Jaminan Uang Muka (Advance Payment Bond)","description":"Dipakai kontraktor untuk mencairkan uang muka (biasanya 20% - 30% nilai kontrak). Menjamin uang muka dipergunakan semestinya dan akan dikembalikan secara bertahap lewat pemotongan termin progres pekerjaan.","badge":"Nilai jaminan: 100% dari nilai uang muka"},{"icon":"HardHat","title":"Jaminan Pemeliharaan (Maintenance Bond)","description":"Sebagai pengganti retensi kas 5% setelah serah terima pertama (BAST 1). Menjamin perbaikan cacat mutu pekerjaan selama masa garansi (3 - 12 bulan) sehingga arus kas kontraktor tetap cair maksimal.","badge":"Pencairan dana retensi kas 100%"},{"icon":"Shield","title":"Asuransi CAR (Contractor All Risk)","description":"Memberikan perlindungan all-risk terhadap kerusakan fisik proyek selama masa konstruksi (kebakaran, gempa, tanah longsor, roboh) dan perlindungan tuntutan pihak ketiga (Third Party Liability / TPL).","badge":"Perlindungan material & pihak ketiga"},{"icon":"Layers","title":"Bank Garansi Non-Collateral","description":"Fasilitas penerbitan warkat resmi bank umum tanpa perlu memblokir dana kas 100%. Membantu kontraktor yang sedang menangani banyak proyek sekaligus agar modal kerja tetap berputar leluasa.","badge":"Legal, resmi & diverifikasi bank"}]},"steps":{"eyebrow":"PROSES MUDAH & TRANSPARAN","title":"4 Langkah Cepat Penerbitan Jaminan","items":[{"step":"1","title":"Kirim Dokumen","description":"Kirimkan salinan legalitas perusahaan dan dokumen tender (RKS/SPK/Kontrak) via WhatsApp atau email."},{"step":"2","title":"Analisis & Draft","description":"Tim analis menghitung tarif premi terbaik dan menerbitkan draft warkat untuk persetujuan (approval) Anda."},{"step":"3","title":"Penerbitan Asli","description":"Warkat resmi diterbitkan oleh bank atau asuransi rekanan lengkap dengan nomor register dan konfirmasi keabsahan."},{"step":"4","title":"Pengiriman Warkat","description":"Hardcopy warkat dikirim kilat ke kantor Anda di seluruh Indonesia, softcopy dikirim segera via WhatsApp/Email."}]},"cta":{"eyebrow":"KONSULTASI GRATIS & CEPAT","title":"Butuh Jaminan Tender Hari Ini?","description":"Diskusikan kebutuhan proyek Anda bersama tim konsultan PT Niaga Jaminan Nusantara. Kami siap membantu kalkulasi premi dan pengurusan tanpa ribet.","whatsappButtonText":"Chat WhatsApp","formButtonText":"Form Pengajuan"},"seo":{"title":"Produk & Layanan Kami - Bank Garansi, Surety Bond & Asuransi Proyek | PT Niaga Jaminan Nusantara","description":"Melayani berbagai kebutuhan jaminan dan asuransi untuk mendukung kesuksesan proyek dan bisnis Anda: Surety Bond, Bank Garansi Non-Collateral, Asuransi Konstruksi (CAR), Asuransi Umum (CGL), Professional Indemnity, Cargo & Engineering.","keywords":["Produk dan Layanan","Surety Bond","Bank Garansi","Bid Bond","Performance Bond","Advance Payment Bond","Maintenance Bond","Bank Garansi Non-Collateral","Asuransi Konstruksi CAR","Commercial General Liability CGL","Professional Indemnity","Marine Cargo Insurance","Engineering Insurance","PT Niaga Jaminan Nusantara"]}}'::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.pages (id, title, content)
VALUES (
  'kontak',
  'Kontak Kami',
  '{"header":{"tagline":"PT NIAGA JAMINAN NUSANTARA","title":"Kontak & Formulir Konsultasi Proyek","description":"Hubungi konsultan kami atau isi formulir di bawah ini untuk konsultasi kelayakan dokumen tender dan penerbitan Bank Garansi & Surety Bond tanpa agunan. Respon cepat dalam 10-15 menit.","badgeText":"Respon Cepat WhatsApp 24 Jam"},"form":{"eyebrow":"FORMULIR KONTAK","title":"Kirim Pesan Kepada Kami","description":"Silakan isi nama, email, dan pesan Anda di bawah ini. Tim kami akan segera menindaklanjuti.","nameLabel":"Nama Lengkap *","namePlaceholder":"Masukkan nama lengkap Anda","emailLabel":"Alamat Email *","emailPlaceholder":"nama@email.com","messageLabel":"Pesan / Message *","messagePlaceholder":"Tuliskan pesan, pertanyaan, atau rincian kebutuhan Anda di sini...","privacyGuarantee":"Jaminan Privasi: Data dan pesan Anda terjamin 100% aman dan rahasia.","submitText":"Kirim Pesan","submitLoadingText":"Mengirimkan Pesan...","successTitle":"Pesan Berhasil Terkirim!","successDescription":"Jendela chat WhatsApp konsultan telah dibuka dengan format pesan Anda. Kami akan segera merespons pertanyaan Anda."},"info":{"eyebrow":"INFORMASI RESMI","title":"Kontak Detail Perusahaan","addressBadge":"Kantor Operasional","addressTitle":"Gedung Graha Surveyor Indonesia Lantai 15","addressDetail":"Jl. Gatot Subroto Kav. 56, Kuningan Barat, Mampang Prapatan, Jakarta Selatan, DKI Jakarta 12950","whatsappBadge":"WhatsApp Konsultan (Chat Cepat)","whatsappNumber":"6282113189343","whatsappDisplay":"0821-1318-9343","whatsappSubtext":"Layanan konsultasi online siap merespons 24/7.","phoneBadge":"Hotline Telepon","phoneNumber":"082113189343","phoneDisplay":"0821-1318-9343","phoneSubtext":"Telepon langsung tim representatif kami.","emailBadge":"Email Resmi","email":"info@anugrahluasjaya.co.id","emailSubtext":"Kirimkan berkas RKS / Dokumen Pemilihan tender via email.","hoursBadge":"Jam Operasional Kantor","hoursWeekday":"Senin – Jumat: 08.00 – 18.00 WIB","hoursSaturday":"Sabtu: 08.00 – 14.00 WIB","hoursSunday":"Minggu & Libur: Layanan WA Tetap Aktif"},"map":{"title":"Peta Lokasi Graha Surveyor","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Graha+Surveyor+Indonesia+Jl+Gatot+Subroto+Kav+56+Jakarta+Selatan","embedUrl":"https://maps.google.com/maps?q=Graha+Surveyor+Indonesia+Jl+Gatot+Subroto+Kav+56+Jakarta+Selatan&t=&z=15&ie=UTF8&iwloc=&output=embed","caption":"Lokasi strategis di koridor Gatot Subroto, dekat kawasan Kuningan & Semanggi Jakarta Selatan."},"regions":{"title":"Layanan Penjaminan Seluruh Indonesia","items":["Jabodetabek","Jawa & Bali","Sumatera","Kalimantan","Sulawesi","Nusa Tenggara & Papua"]},"faqs":{"eyebrow":"PERTANYAAN UMUM","title":"Seputar Konsultasi & Pengajuan Warkat","items":[{"icon":"HelpCircle","question":"Apakah ada biaya konsultasi?","answer":"Sama sekali tidak ada biaya (100% Gratis). Anda bebas berkonsultasi mengenai kelayakan dokumen tender dan perhitungan tarif premi."},{"icon":"FileCheck2","question":"Berapa lama proses penerbitan?","answer":"Untuk Surety Bond butuh 1-2 hari kerja. Untuk Bank Garansi berkisar 2-3 hari kerja setelah seluruh dokumen legalitas dan RKS dinyatakan lengkap."},{"icon":"Zap","question":"Apakah bisa kirim berkas lewat WhatsApp?","answer":"Sangat bisa. Anda dapat mengirimkan softcopy dokumen tender (format PDF) langsung ke WhatsApp konsultan kami untuk verifikasi awal yang cepat."}]},"seo":{"title":"Kontak Kami - Konsultasi Bank Garansi & Surety Bond | PT Niaga Jaminan Nusantara","description":"Hubungi PT Niaga Jaminan Nusantara untuk konsultasi gratis penerbitan Bank Garansi & Surety Bond tanpa agunan (non-collateral). Kantor di Graha Surveyor Indonesia Lt. 15, Jakarta Selatan. WhatsApp: 0821-1318-9343.","keywords":["Kontak Bank Garansi","Konsultasi Surety Bond","PT Niaga Jaminan Nusantara","Kantor PT Niaga Jaminan Nusantara","Alamat Graha Surveyor Indonesia","WhatsApp Bank Garansi","Agen Asuransi Tender Proyek","Jasa Bank Garansi Jakarta"]}}'::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.pages (id, title, content)
VALUES (
  'syarat-ketentuan',
  'Syarat & Ketentuan',
  '{"header":{"tagline":"PT NIAGA JAMINAN NUSANTARA","title":"Persyaratan Penerbitan Bank Garansi & Surety Bond","description":"Dokumen legalitas utama perusahaan yang wajib dilampirkan oleh Principal (Pelaksana Proyek) sebagai syarat underwriting dan verifikasi awal oleh pihak Bank maupun Asuransi penjamin:"},"legalChecklist":{"title":"Checklist Dokumen Legalitas Perusahaan","subtitle":"Wajib dilengkapi untuk pengajuan penerbitan jaminan proyek","items":[{"title":"Akte Pendirian Beserta Perubahan Terakhir","description":"Melampirkan salinan akta pendirian perusahaan dan akta perubahan susunan pengurus/modal terakhir."},{"title":"SK MENKEH, SIUJK, SIUP, TDP / NIB, & NPWP","description":"Surat Keputusan Kemenkumham, Izin Usaha Jasa Konstruksi, NIB / SIUP / TDP, serta NPWP Badan Usaha yang masih berlaku."},{"title":"Keterangan Domisili","description":"Surat Keterangan Domisili Perusahaan (SKDP) atau bukti domisili kantor resmi."},{"title":"Mengisi Form Permohonan Penjaminan","description":"Mengisi formulir permohonan resmi yang ditujukan ke pihak asuransi atau bank penerbit (form kami sediakan)."},{"title":"Melampirkan List Pengalaman Pekerjaan","description":"Daftar rekam jejak pekerjaan (track record) atau proyek yang pernah diselesaikan oleh perusahaan dalam 1-3 tahun terakhir."},{"title":"Laporan Keuangan 2 Tahun Terakhir","description":"Laporan keuangan internal atau audit 2 tahun terakhir yang memuat neraca aktiva-pasiva dan laporan rugi laba."},{"title":"Photocopy KTP Direksi dan Komisaris Selaku Pengurus","description":"Salinan identitas sah KTP seluruh Direksi dan Dewan Komisaris yang tercantum dalam akta perusahaan."}]},"sidebar":{"efficiencyTitle":"Kirim Dokumen via WhatsApp / Email","efficiencyDescription":"Untuk mempercepat proses review dan draft penerbitan jaminan, seluruh dokumen cukup dikirimkan dalam format scan **PDF** via WhatsApp atau Email tanpa harus datang ke kantor kami.","efficiencyButtonText":"Kirim Berkas PDF ke WhatsApp","helpTitle":"Ada Dokumen yang Belum Lengkap?","helpDescription":"Jangan khawatir! Tim konsultan **PT NIAGA JAMINAN NUSANTARA** siap membantu pendampingan dan memberikan solusi terbaik agar jaminan Anda tetap dapat diterbitkan tepat waktu sebelum tenggat lelang atau proyek.","helpLinkText":"Konsultasikan Masalah Dokumen"},"productRequirements":{"eyebrow":"PERSYARATAN KHUSUS TIAP PRODUK","title":"Persyaratan Dokumen Sesuai Jenis Jaminan","description":"Selain dokumen legalitas dasar di atas, lampirkan dokumen pendukung spesifik sesuai dengan jenis jaminan yang Anda ajukan:","cards":[{"icon":"FileCheck2","stageBadge":"Tahap Tender","title":"Persyaratan Jaminan Penawaran (Bid Bond)","description":"Dibutuhkan untuk memenuhi syarat pendaftaran dan keikutsertaan tender / lelang proyek pemerintah maupun swasta.","items":["Melampirkan **company profile** dan legalitas perusahaan lengkap.","Melampirkan **laporan keuangan 2 tahun terakhir** dan neraca rugi laba.","Melampirkan **list pengalaman pekerjaan** perusahaan.","Melampirkan **dokumen lelang atau tender** (RKS, Undangan Tender, atau Pengumuman Lelang)."],"estimatedTime":"Estimasi Terbit: 1 Hari Kerja","buttonText":"Ajukan Bid Bond"},{"icon":"ShieldCheck","stageBadge":"Tahap Pemenang","title":"Persyaratan Jaminan Pelaksanaan (Performance Bond)","description":"Menjamin bahwa pemenang lelang akan menandatangani kontrak dan menyelesaikan proyek sesuai spesifikasi.","items":["Melampirkan **company profile** dan legalitas perusahaan lengkap.","Melampirkan **laporan keuangan 2 tahun terakhir** dan neraca rugi laba.","Melampirkan **list pengalaman pekerjaan** perusahaan.","Melampirkan **surat penunjukan pemenang lelang / SPPBJ / SPK / SPMK / Kontrak**."],"estimatedTime":"Estimasi Terbit: 1-2 Hari Kerja","buttonText":"Ajukan Performance Bond"},{"icon":"Coins","stageBadge":"Pencairan DP Proyek","title":"Persyaratan Jaminan Uang Muka (Advance Payment Bond)","description":"Dibutuhkan untuk mencairkan uang muka / Down Payment (DP) proyek dari pihak pemilik proyek (Obligee).","items":["Melampirkan **company profile** dan legalitas perusahaan lengkap.","Melampirkan **laporan keuangan 2 tahun terakhir** dan neraca rugi laba.","Melampirkan **list pengalaman pekerjaan** perusahaan.","Melampirkan **kontrak / purchase order (PO) / letter of intent (LOI) / work order (WO)**."],"estimatedTime":"Estimasi Terbit: 1-2 Hari Kerja","buttonText":"Ajukan Advance Bond"},{"icon":"Wrench","stageBadge":"Masa Garansi","title":"Persyaratan Jaminan Pemeliharaan (Maintenance Bond)","description":"Menjamin perbaikan atas kerusakan fisik selama masa garansi/pemeliharaan setelah pekerjaan selesai 100%.","items":["Melampirkan **company profile** dan legalitas perusahaan lengkap.","Melampirkan **laporan keuangan 2 tahun terakhir** dan neraca rugi laba.","Melampirkan **list pengalaman pekerjaan** perusahaan.","Melampirkan **kontrak dan Berita Acara Serah Terima pekerjaan (BAST)**."],"estimatedTime":"Estimasi Terbit: 1-2 Hari Kerja","buttonText":"Ajukan Maintenance Bond"}]},"steps":{"eyebrow":"PROSES CEPAT & TRANSPARAN","title":"4 Langkah Mudah Penerbitan Jaminan","items":[{"step":"1","title":"Kirim Dokumen","description":"Kirim softcopy/scan dokumen legalitas dan dokumen lelang/kontrak Anda via WhatsApp atau Email."},{"step":"2","title":"Verifikasi & Draft","description":"Tim analis melakukan verifikasi kelayakan dan menerbitkan konsep draft polis untuk Anda setujui."},{"step":"3","title":"Pembayaran Premi","description":"Lakukan pembayaran premi resmi setelah draft penjaminan diverifikasi dan disetujui."},{"step":"4","title":"Penerbitan & Kirim","description":"Sertifikat / Warkat Bank Garansi dan Polis Asli langsung dicetak dan dikirimkan ke alamat Anda."}]},"cta":{"eyebrow":"KONSULTASI BEBAS BIAYA","title":"PT NIAGA JAMINAN NUSANTARA","description":"Segera konsultasikan kebutuhan penerbitan Bank Garansi dan Surety Bond proyek Anda bersama konsultan ahli kami. Proses cepat, syarat fleksibel, dan legalitas resmi terverifikasi.","whatsappButtonText":"HUBUNGI KAMI (0821-1318-9343)","formButtonText":"Formulir Permohonan Online"},"seo":{"title":"Syarat & Ketentuan Penerbitan Bank Garansi dan Surety Bond | PT Niaga Jaminan Nusantara","description":"Persyaratan lengkap penerbitan Bank Garansi dan Surety Bond (Bid Bond, Performance Bond, Advance Payment Bond, Maintenance Bond) PT Niaga Jaminan Nusantara. Proses cepat, syarat ringan, dan terpercaya.","keywords":["Syarat Bank Garansi","Persyaratan Surety Bond","Syarat Bid Bond","Syarat Performance Bond","Syarat Advance Payment Bond","Syarat Maintenance Bond","PT Niaga Jaminan Nusantara","Dokumen Penerbitan Bank Garansi"]}}'::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.pages (id, title, content)
VALUES (
